          "search_text": "260710 玻璃基板 mapping 一级市场 玻璃基板类型 玻璃基板封装 公司类型 电子元件 公司名称 成都迈科科技有限公司 地区 四川省-成都市 成立时间 2017-06-27 业务描述 后摩尔时代三维封装基板提供商 核心产品/技术 后摩尔时代三维封装基板提供商 融资轮次 a轮 最新融资金额 亿级人民币 主要投资方 元禾璞华,隐山资本,金控发展基金,成都高科,励石创投,成都交子产业基金,成都高投集团 公司团队 张继华，职务：创始人&董事长，介绍：张继华：电子科技大学教授，博士生导师。1998年毕业于兰州大学物理系，2004年毕业于中科院上海微系统与信息技术研究所获博士学位(师从王曦院士)。主要从事微系统关键材料与集成技术方向的教学和科研工作。先后作为项目负责人主持973重大基础研究子课题、国家自然科学基金、产学研重大专项及jwkjw、装发、科工局等科研项目30余项；在carbon、appl.phys.lett、nanotechnology等sci刊物上发表论文100余篇；会议邀请报告5次；获授权国家发明专利10余项。研究的三维集成玻璃转接板、ipd薄膜集成器件、脉冲电容器、微波介质陶瓷等已用于军用电子器件研制；在薄膜集成器件产业化关键技术上取得突破，2010-2015新增产值2.5亿元。2017年作为“功能材料与集成器件团队”核心成员获“全国创新争先奖牌”(仅次于国家最高科技奖的科技人才大奖)，2018年获四川省技术发明三等奖（排名第一）、重庆市自然科学三等奖。2017年作为创始人创立成都迈科科技有限公司，致力于领跑后摩尔时代集成电路基板与三维集成技术。 公司简介 成都迈科成立于2017年6月，是一个后摩尔时代三维封装基板提供商，主要产品包括三维集成转接板、ipd无源集成器件（aip封装天线、毫米波滤波器、芯片电感等）和3d玻璃（传感器基板、折叠屏背板、电子烟雾化芯、原子钟碱金属气室等）。 官网 http://cdmicrotech.com/ 地址 成都高新区西芯大道4号创新中心d136号 联系电话 13981926334 邮箱 market_microtech@163.com",
