          "search_text": "260710 玻璃基板 mapping 一级市场 玻璃基板类型 玻璃基板材料 公司类型 光学薄膜 公司名称 深圳市矩阵多元科技有限公司 地区 广东省-深圳市 成立时间 2016-12-07 业务描述 薄膜材料制备和高通量材料制备系统开发商 核心产品/技术 薄膜材料制备和高通量材料制备系统开发商 融资轮次 b++轮 最新融资金额 亿元级人民币（b2轮） 主要投资方 中车资本、智慧互联产业基金、前海母基金、毅达资本（b2轮）；毅达资本（b++轮） 公司团队 张晓军，职务：董事长&创始合伙人，介绍：张晓军，深圳市矩阵多元科技有限公司董事长、创始合伙人。毕业于加州大学伯克利分校机械工程系，曾任美国应用材料、美国西部数据首席研发工程师。曾经在多家世界著名大学，国家实验室及公司从事材料和相关张晓军博士--设备的研发、包括美国lavene bekelev国家实验室、南京大学国体微结构国家实验室，美国应用材料和美国西部数据，目前在材料领域发表学术论文20多篇、拥有30多项中美专利、在西部数据和应用材料多次获得技术发明奖，曾获得伯克利工程学anseino ohn macchi奖学金。同时，担任scentihcrepots等十多家材料学领域学术杂志的审稿人。曾入选2020年科技部创新人才推进计划科技创新创业人才。 公司简介 深圳市矩阵多元科技有限公司(矩阵科技)是一家专注于薄膜材料制备和高通量材料制备系统开发及应用的国家高新技术企业，公司主营设备包括科研型及生产型薄膜材料制备系统:脉冲激光沉积系统、磁控溅射系统、电子東蒸发系统、分子束外延系统等离子体增强化学气相沉积系统等矩阵科技团队成员来自加州大学伯克利分校以及全球五百强公司美国applied materials，western digital，东京电子和多所国家实验室，拥有数十年设备开发及材料研发经验。公司搭建的基于脉冲激光沉积技术及磁控溅射技术的高通量材料制备系统平台可一次性批量制备100种不同材料配方或不同工艺的材料，并可同时对多达100种材料样品进行快速自动化测试和筛选。相对于传统的一个个材料试错过程，此平台可大大缩短新材料研发周期降低研发成本，加速新材料的研发及应用 官网 http://www.arrayedmaterials.com 地址 深圳市龙华区民治街道上芬社区龙屋工业区6号厂房101一、二楼 联系电话 0755-86707697 邮箱 35",
