        "intro": "成都迈科成立于2017年6月，是一个后摩尔时代三维封装基板提供商，主要产品包括三维集成转接板、IPD无源集成器件（AIP封装天线、毫米波滤波器、芯片电感等）和3D玻璃（传感器基板、折叠屏背板、电子烟雾化芯、原子钟碱金属气室等）。",
        "team": "张继华，职务：创始人&董事长，介绍：张继华：电子科技大学教授，博士生导师。1998年毕业于兰州大学物理系，2004年毕业于中科院上海微系统与信息技术研究所获博士学位(师从王曦院士)。主要从事微系统关键材料与集成技术方向的教学和科研工作。先后作为项目负责人主持973重大基础研究子课题、国家自然科学基金、产学研重大专项及JWKJW、装发、科工局等科研项目30余项；在Carbon、Appl.Phys.Lett、Nanotechnology等SCI刊物上发表论文100余篇；会议邀请报告5次；获授权国家发明专利10余项。研究的三维集成玻璃转接板、IPD薄膜集成器件、脉冲电容器、微波介质陶瓷等已用于军用电子器件研制；在薄膜集成器件产业化关键技术上取得突破，2010-2015新增产值2.5亿元。2017年作为“功能材料与集成器件团队”核心成员获“全国创新争先奖牌”(仅次于国家最高科技奖的科技人才大奖)，2018年获四川省技术发明三等奖（排名第一）、重庆市自然科学三等奖。2017年作为创始人创立成都迈科科技有限公司，致力于领跑后摩尔时代集成电路基板与三维集成技术。",
